CREATE TABLE IF NOT EXISTS platform_commercial_plans (
 id TEXT PRIMARY KEY, settings JSONB NOT NULL, defaults JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
